export interface System {
  /** Unique system name. */
  name: string;
  /** Names of systems that must run before this one. */
  after?: string[];
  /** Names of systems that must run after this one. */
  before?: string[];
}

/**
 * Topologically sorts systems by their `before`/`after` constraints.
 * Declaration order is used as the stable tie-break between
 * unordered systems. Throws a descriptive error when constraints
 * form a cycle, listing all cycle members.
 */
export function scheduleSystems(systems: readonly System[]): System[] {
  const byName = new Map<string, System>();
  for (const sys of systems) {
    if (byName.has(sys.name)) {
      throw new Error(`Duplicate system name: "${sys.name}"`);
    }
    byName.set(sys.name, sys);
  }

  // Edges: predecessor -> successors (predecessor runs first).
  const edges = new Map<string, Set<string>>();
  const indegree = new Map<string, number>();
  for (const sys of systems) {
    if (!edges.has(sys.name)) edges.set(sys.name, new Set());
    indegree.set(sys.name, 0);
  }

  const addEdge = (from: string, to: string) => {
    let targets = edges.get(from)!;
    if (!targets.has(to)) {
      targets.add(to);
      indegree.set(to, indegree.get(to)! + 1);
    }
  };

  for (const sys of systems) {
    for (const dep of sys.after ?? []) {
      if (!byName.has(dep)) {
        throw new Error(
          `System "${sys.name}" depends on unknown system "${dep}"`
        );
      }
      addEdge(dep, sys.name);
    }
    for (const succ of sys.before ?? []) {
      if (!byName.has(succ)) {
        throw new Error(
          `System "${sys.name}" must run before unknown system "${succ}"`
        );
      }
      addEdge(sys.name, succ);
    }
  }

  // Kahn's algorithm; declaration order breaks ties.
  const ready: string[] = systems
    .filter((s) => indegree.get(s.name) === 0)
    .map((s) => s.name);

  const result: System[] = [];
  while (ready.length > 0) {
    const name = ready.shift()!;
    result.push(byName.get(name)!);
    for (const succ of edges.get(name)!) {
      const deg = indegree.get(succ)! - 1;
      indegree.set(succ, deg);
      if (deg === 0) ready.push(succ);
    }
  }

  if (result.length !== systems.length) {
    const remaining = systems.filter((s) => indegree.get(s.name)! > 0).map((s) => s.name);
    throw new Error(
      `Cyclic dependency among systems: ${remaining.join(", ")}`
    );
  }

  return result;
}

