import { describe, expect, it } from "vitest";
import { scheduleSystems } from "../src/scheduler.js";

const names = (systems: { name: string }[]) => systems.map((s) => s.name);

describe("scheduleSystems", () => {
  it("orders a diamond dependency respecting all constraints", () => {
    const ordered = scheduleSystems([
      { name: "Input" },
      { name: "Movement", after: ["Input"] },
      { name: "AI", after: ["Input"] },
      { name: "Collision", after: ["Movement", "AI"] },
    ]);

    const order = names(ordered);
    expect(order.indexOf("Input")).toBeLessThan(order.indexOf("Movement"));
    expect(order.indexOf("Input")).toBeLessThan(order.indexOf("AI"));
    expect(order.indexOf("Movement")).toBeLessThan(order.indexOf("Collision"));
    expect(order.indexOf("AI")).toBeLessThan(order.indexOf("Collision"));
  });

  it("throws on cycles and names all participants", () => {
    const systems = [
      { name: "Input", before: ["Collision"] },
      { name: "Collision" },
      { name: "AI", before: ["Input"] },
      { name: "Movement", after: ["AI"] },
    ];

    let error!: Error;
    try {
      scheduleSystems(systems);
    } catch (e) {
      error = e as Error;
    }

    expect(error).toBeInstanceOf(Error);
    for (const participant of ["Input", "Collision", "AI"]) {
      expect(error.message).toContain(participant);
    }
  });

  it("keeps declaration order for independent systems", () => {
    const ordered = scheduleSystems([
      { name: "Render" },
      { name: "Audio" },
      { name: "Network" },
    ]);

    expect(names(ordered)).toEqual(["Render", "Audio", "Network"]);
  });
});

