export interface System {
  /** Unique system name. */
  name: string;
  /** Names of systems that must run before this one. */
  after?: string[];
  /** Names of systems that must run after this one. */
  before?: string[];
}

/**
 * Topologically sorts systems by their `before`/`after` constraints.
 * Declaration order is used as the stable tie-break between
 * unordered systems. Throws a descriptive error when constraints
 * form a cycle, listing the members of the offending cycle.
 */
export function scheduleSystems(systems: readonly System[]): System[] {
  const byName = new Map<string, System>();
  for (const sys of systems) {
    if (byName.has(sys.name)) {
      throw new Error(`Duplicate system name: "${sys.name}"`);
    }
    byName.set(sys.name, sys);
  }

  // Edges: predecessor -> successors (predecessor must run first).
  const successors = new Map<string, string[]>();
  for (const sys of systems) {
    const targets = new Set(successors.get(sys.name) ?? []);
    for (const dep of sys.after ?? []) {
      if (!byName.has(dep)) {
        throw new Error(
          `System "${sys.name}" depends on unknown system "${dep}"`
        );
      }
      targets.add(dep);
    }
    for (const succ of sys.before ?? []) {
      if (!byName.has(succ)) {
        throw new Error(
          `System "${sys.name}" must run before unknown system "${succ}"`
        );
      }
      targets.add(succ);
    }
    successors.set(sys.name, [...targets]);
  }

  // Depth-first topological sort with declaration-order iteration,
  // detecting cycles and reporting the cycle's members.
  const WHITE = 0;
  const GRAY = 1;
  const BLACK = 2;
  const color = new Map<string, number>(systems.map((s) => [s.name, WHITE]));
  const result: System[] = [];

  const visit = (name: string, stack: string[]): void => {
    if (color.get(name) === GRAY) {
      const start = stack.indexOf(name);
      const cycle = [...stack.slice(start), name];
      throw new Error(`Cyclic dependency among systems: ${cycle.join(" -> ")}`);
    }
    if (color.get(name) === BLACK) return;

    color.set(name, GRAY);
    stack.push(name);
    for (const succ of successors.get(name)!) {
      visit(succ, stack);
    }
    stack.pop();
    color.set(name, BLACK);
    result.push(byName.get(name)!);
  };

  for (const sys of systems) {
    if (color.get(sys.name) === WHITE) visit(sys.name, []);
  }

  return result.reverse();
}

