  // Depth-first pass to detect cycles and report the cycle's members.
  const WHITE = 0;
  const GRAY = 1;
  const BLACK = 2;
  const color = new Map<string, number>(systems.map((s) => [s.name, WHITE]));

  const visit = (name: string, stack: string[]): void => {
    if (color.get(name) === GRAY) {
      const start = stack.indexOf(name);
      const cycle = [...stack.slice(start), name];
      throw new Error(`Cyclic dependency among systems: ${cycle.join(" -> ")}`);
    }
    if (color.get(name) === BLACK) return;

    color.set(name, GRAY);
    stack.push(name);
    for (const succ of successors.get(name)!) {
      visit(succ, stack);
    }
    stack.pop();
    color.set(name, BLACK);
  };

  for (const sys of systems) {
    if (color.get(sys.name) === WHITE) visit(sys.name, []);
  }

  // Kahn's algorithm with declaration order as the stable tie-break.
  const result: System[] = [];
  const remaining = new Set(systems.map((s) => s.name));
  while (remaining.size > 0) {
    const ready = systems.find(
      (s) => remaining.has(s.name) && indegree.get(s.name) === 0
    );
    if (!ready) {
      // Unreachable in practice: DFS above already rejects cycles.
      throw new Error("Cyclic dependency detected among systems");
    }
    remaining.delete(ready.name);
    result.push(ready);
    for (const succ of successors.get(ready.name)!) {
      indegree.set(succ, indegree.get(succ)! - 1);
    }
  }

  return result;
}

