  // The valid diamond from above, plus "Collision runs before Input".
  const systems = [
    { name: "Input" },
    { name: "Movement", after: ["Input"] },
    { name: "AI", after: ["Input"] },
    { name: "Collision", after: ["Movement", "AI"], before: ["Input"] },
  ];

  let error!: Error;
  try {
    scheduleSystems(systems);
  } catch (e) {
    error = e as Error;
  }

  expect(error).toBeInstanceOf(Error);
  expect(error.message).toContain("Cyclic dependency");
